-- ============================================================
-- 003 — Drill seed, part 06 of 07  (40 drills)
--
-- Paste into the Supabase SQL editor and run. Parts are independent and
-- idempotent: re-running one updates those rows rather than duplicating them.
--
-- Requires scripts/002_drill_content.sql to have been applied first.
-- ============================================================

INSERT INTO public.drills (
  slug, name, category, subcategory, type, level, duration_min, player_count, group_size, description, objective, setup, instructions, coaching_cues, common_errors, variations, tags, diagram_type, diagram_data
) VALUES
  ('RT-016', 'Return Placement Game: Server vs Returner', 'Return', 'Tactical', 'return', 'intermediate', 15, 2, 'pairs', 'Develop return placement under competitive pressure through a structured guessing game. The server must guess where the return will go — the returner scores by going the opposite direction. This game makes the returner think tactically about disguise and placement rather than just trying to hit the ball in, and makes the server think about what patterns the returner is using.', 'Develop return placement under competitive pressure through a structured guessing game. The server must guess where the return will go — the returner scores by going the opposite direction. This game makes the returner think tactically about disguise and placement rather than just trying to hit the ball in, and makes the server think about what patterns the returner is using.', 'Player 2 serves from both courts. Before Player 1 returns, Player 2 guesses ''cross'' or ''line''. Player 1 must go the opposite direction. Player 1 scores if Player 2 guesses wrong; Player 2 scores if correct. First to 10 wins.', ARRAY['Player 2 serves from the deuce court.','Player 2 calls ''cross'' or ''line'' immediately before or as Player 1 hits the return.','Player 1 must return the opposite direction of Player 2''s call.','Player 1 scores +1 for going the wrong direction from the guess.','Player 2 scores +1 for guessing correctly. First to 10 points wins.']::text[], ARRAY['Player 1: watch Player 2''s call and react — but also try to disguise the setup.','Player 1: if Player 2 always guesses ''cross'', just go cross-court every time — exploit predictability.','Player 2: watch the return setup to predict — contact point, racket face, body position are all tells.','Player 1: keep the same preparation for both directions — the switch happens at contact.','This game reveals your tells — if Player 2 guesses correctly more than 60%, you are telegraphing.']::text[], ARRAY['Player 1 telegraphing the direction with a different setup — Player 2 reads it before the guess.','Player 2 always guessing the same direction — not actually reading, just gambling.','Player 1 making poor contact in trying to change direction — placement must not hurt quality.']::text[], ARRAY['Add a third option: Player 2 can also call ''body'' — Player 1 must go anywhere except the body.','Role reversal: Player 1 becomes the server and guesser after 10 points.','Full point version: after the return, play out the point — add real match consequences.']::text[], ARRAY['return','placement','game','intermediate','tactical','disguise']::text[], 'json', '{"p1":{"x":280,"y":60},"p2":{"x":240,"y":860},"shots":[{"x1":240,"y1":850,"x2":310,"y2":385},{"x1":280,"y1":65,"x2":110,"y2":820},{"x1":280,"y1":65,"x2":295,"y2":820}],"areas":[{"x":110,"y":820,"r":25},{"x":295,"y":820,"r":25}]}'::jsonb),
  ('RT-017', 'Return from Ad Court: Wide and T', 'Return', 'Placement', 'return', 'intermediate', 12, 2, 'pairs', 'Train return from the ad court — the most pressure-laden return position in tennis. The ad court return is played at deuce and at ad-out, the two highest-pressure points in a game. This drill trains both the wide ad serve return and the T ad serve return, building the specific return patterns most needed in tight, high-pressure moments.', 'Train return from the ad court — the most pressure-laden return position in tennis. The ad court return is played at deuce and at ad-out, the two highest-pressure points in a game. This drill trains both the wide ad serve return and the T ad serve return, building the specific return patterns most needed in tight, high-pressure moments.', 'Player 2 serves from the ad court to Player 1 on the ad side. Player 2 alternates between wide (to Player 1''s backhand) and T (to Player 1''s forehand). Player 1 must read the serve and return appropriately.', ARRAY['Player 2 serves wide from the ad court — to Player 1''s backhand.','Player 1 returns cross-court (to deuce side) with a chip or drive.','After 5 wide returns, Player 2 serves T — to Player 1''s forehand.','Player 1 returns cross-court (to ad side) or DTL.','Alternate 5 wide, 5 T, then mix randomly for 10 more. Total: 20 returns per set.']::text[], ARRAY['Ad court wide serve: to your backhand — chip cross-court is the safest and most effective response.','Ad court T serve: to your forehand — drive cross-court or go inside-in forehand.','The ad court wide serve is the most common pressure serve — practice it most.','From the ad court, the cross-court return goes to the deuce side — where the server wants to avoid.','At deuce and ad-out, breathe before the return — the point matters, the technique should not change.']::text[], ARRAY['Going DTL off the wide ad court serve — very high risk from a wide backhand position.','Chipping the T serve when a drive was available — giving up a free attack opportunity.','Changing the return under pressure — most errors in the ad court come from overthinking.']::text[], ARRAY['Pressure simulation: start every return point at deuce — full mental pressure.','Ad court return and win: Player 1 must win the point after the return — full point play.','Ad court consistency: 8 out of 10 wide ad returns must land cross-court past the service line.']::text[], ARRAY['return','ad court','wide','T serve','intermediate','pressure']::text[], 'json', '{"p1":{"x":120,"y":60},"p2":{"x":160,"y":860},"shots":[{"x1":160,"y1":850,"x2":80,"y2":388},{"x1":120,"y1":65,"x2":295,"y2":820},{"x1":160,"y1":850,"x2":200,"y2":385},{"x1":120,"y1":65,"x2":100,"y2":820}],"areas":[{"x":295,"y":820,"r":25},{"x":100,"y":820,"r":25}]}'::jsonb),
  ('RT-018', 'Lob Return: When to Lob the Serve', 'Return', 'Tactical', 'return', 'intermediate', 10, 2, 'pairs', 'Develop the lob return — a high, deep return used in specific tactical situations: against serve-and-volleyers who rush the net, when the returner is pulled extremely wide, or as a surprise element to disrupt a server''s rhythm. The lob return is underused by most club players and devastatingly effective when used at the right moment.', 'Develop the lob return — a high, deep return used in specific tactical situations: against serve-and-volleyers who rush the net, when the returner is pulled extremely wide, or as a surprise element to disrupt a server''s rhythm. The lob return is underused by most club players and devastatingly effective when used at the right moment.', 'Player 2 serves and rushes the net on every serve — simulating a serve-and-volleyer. Player 1 must lob return over Player 2''s head on most serves, with occasional drive returns to keep Player 2 honest.', ARRAY['Player 2 serves and sprints to the net on every serve.','Player 1 lobs return over Player 2''s head — high, deep, landing near the baseline.','After 8 lob returns, Player 1 drives 2 returns — keeps Player 2 from anticipating only lobs.','Switch courts and repeat.','Track: how many lob returns land in the back half of the court? Target: 7 out of 10.']::text[], ARRAY['Open the racket face significantly on the lob return — it must go high.','Aim well over Player 2''s head — not just barely over. Safety first on the lob return.','The lob return must land deep — a short lob return is an overhead opportunity.','Use the lob return when Player 2 is clearly rushing the net — read the intention.','Mix the lob return with the occasional drive — the server must not know which is coming.']::text[], ARRAY['Lob return not going high enough — Player 2 smashes an easy overhead.','Lob return landing short — gives Player 2 a comfortable overhead from mid-court.','Using lob return too often — becomes predictable and Player 2 starts hanging back.']::text[], ARRAY['Lob return competition: Player 2 tries to overhead every lob, Player 1 tries to lob out of reach.','Surprise lob: Player 2 does not rush the net — Player 1 must choose when to lob independently.','Topspin lob return: add topspin to the lob — harder to smash, bounces further away.']::text[], ARRAY['return','lob','tactical','intermediate','serve-and-volley','surprise']::text[], 'json', '{"p1":{"x":280,"y":60},"p2":{"x":200,"y":560},"moves":[{"x1":240,"y1":860,"x2":200,"y2":560}],"shots":[{"x1":240,"y1":855,"x2":310,"y2":385},{"x1":280,"y1":65,"x2":200,"y2":820}],"areas":[{"x":200,"y":820,"r":35}]}'::jsonb),
  ('RT-019', 'Return Under Time Pressure: Fast Serve Simulation', 'Return', 'Technique', 'return', 'advanced', 12, 2, 'pairs', 'Train the return under extreme time pressure — simulating returning a 120+ mph serve. When the serve is very fast, the returner has almost no time to prepare and must rely on a compact, automatic motion. This drill progressively increases serve pace until Player 1 is returning at the limits of their reaction time, forcing the compact return response to become completely automatic.', 'Train the return under extreme time pressure — simulating returning a 120+ mph serve. When the serve is very fast, the returner has almost no time to prepare and must rely on a compact, automatic motion. This drill progressively increases serve pace until Player 1 is returning at the limits of their reaction time, forcing the compact return response to become completely automatic.', 'Player 2 serves at progressively increasing pace: starting at 50%, increasing to 70%, 85%, then maximum. At each pace level, Player 1 returns 5 balls before the pace increases. Player 2 always serves to the same location so Player 1 can focus on timing, not reading.', ARRAY['Player 2 serves from the deuce court, always to the T, at 50% pace. Player 1 returns 5 balls.','Increase to 70% pace. Player 1 returns 5 balls.','Increase to 85% pace. Player 1 returns 5 balls.','Increase to maximum pace. Player 1 returns 5 balls.','Rest 90 seconds. Repeat to the ad court. Track in-percentage at each pace level.']::text[], ARRAY['At high pace, the backswing must be almost zero — the racket stays in front of the body.','Use the server''s pace — don''t try to generate your own. A wall return is the goal.','Firm wrist is the only consistent element under extreme time pressure.','Move your feet even at maximum pace — one step to the ball makes a critical difference.','Accept that at maximum pace, getting the ball in is the goal — placement comes second.']::text[], ARRAY['Trying to take a backswing at high pace — contact happens before the swing is ready.','Freezing under extreme pace — the body locks up and the ball goes unanswered.','Aiming for a specific target at maximum pace — reduces focus from the ball to the court.']::text[], ARRAY['Mixed pace: Player 2 alternates slow and fast with no warning — Player 1 must adjust each time.','Reaction test: Player 2 serves at maximum pace to random locations — pure reaction return.','Video analysis: film the return at high pace and compare backswing size to low pace — should be shorter.']::text[], ARRAY['return','time pressure','fast serve','advanced','reaction','compact']::text[], 'json', '{"p1":{"x":280,"y":60},"p2":{"x":240,"y":860},"shots":[{"x1":240,"y1":850,"x2":200,"y2":378},{"x1":280,"y1":65,"x2":100,"y2":820}],"areas":[{"x":100,"y":820,"r":30}]}'::jsonb),
  ('RT-020', 'Return Consistency Challenge: 10 in a Row', 'Return', 'Technique', 'return', 'beginner', 10, 2, 'pairs', 'Build return consistency through a count-based challenge — 10 consecutive returns without an error. The return is the most error-prone shot in tennis at club level, and the most common cause of return errors is over-aggression. This drill teaches players that getting the return in consistently is the primary goal, and that even a neutral deep return puts the server under pressure.', 'Build return consistency through a count-based challenge — 10 consecutive returns without an error. The return is the most error-prone shot in tennis at club level, and the most common cause of return errors is over-aggression. This drill teaches players that getting the return in consistently is the primary goal, and that even a neutral deep return puts the server under pressure.', 'Player 2 serves from both courts at moderate pace. Player 1 must return every serve into the court — anywhere in the court counts. Any return into the net or wide resets the count to zero.', ARRAY['Player 2 serves from the deuce court at 70% pace.','Player 1 must return every serve into the court. Count consecutive makes.','Any error resets to zero.','Target: 10 consecutive returns without an error.','Switch to ad court after reaching 10 and repeat.']::text[], ARRAY['Focus on getting the ball in, not on where it goes — consistency before placement.','Aim for a large target: the entire back half of the court. Don''t aim for corners.','Keep the swing relaxed — tight, desperate swings produce errors.','Breathe as you swing — exhale on contact.','After reaching 10, add the constraint: returns must also land past the service line.']::text[], ARRAY['Aiming for specific targets — reduces the effective target area unnecessarily.','Tightening up on serve — the return swing is just a groundstroke.','Resetting the count with too much self-criticism — stay relaxed after misses.']::text[], ARRAY['Increase to 15 or 20 in a row after reaching 10.','Add a placement constraint: must land cross-court after reaching 10 in a row.','Timed version: how many consecutive returns in 5 minutes?']::text[], ARRAY['return','consistency','challenge','beginner','count','mental']::text[], 'json', '{"p1":{"x":280,"y":60},"p2":{"x":240,"y":860},"shots":[{"x1":240,"y1":850,"x2":310,"y2":385},{"x1":280,"y1":65,"x2":180,"y2":820}],"areas":[{"x":180,"y":820,"r":50}]}'::jsonb),
  ('RT-021', 'Return to Target Zones: Three-Corner Accuracy', 'Return', 'Placement', 'return', 'intermediate', 12, 2, 'pairs', 'Develop precise return placement to all three key target zones — cross-court deep, down-the-line, and body of the server. Most players return to the same zone on every serve without conscious thought. This drill trains deliberate, intentional return placement to all three zones, building the tactical flexibility needed in match play.', 'Develop precise return placement to all three key target zones — cross-court deep, down-the-line, and body of the server. Most players return to the same zone on every serve without conscious thought. This drill trains deliberate, intentional return placement to all three zones, building the tactical flexibility needed in match play.', 'Player 2 serves from the deuce court. Three cones mark the three return target zones: cross-court deep, DTL deep, and center (body of the server). Player 2 calls a target zone before each serve — Player 1 must land the return in the called zone.', ARRAY['Player 2 serves from the deuce court and calls a target zone before each serve: ''cross'', ''line'', or ''body''.','Player 1 must return to the called zone.','Score: +2 for landing within 2 feet of the cone, +1 for landing in the correct half.','Play 15 serves per round. Target: 25+ points per round.','Switch to ad court and repeat with the corresponding three zones.']::text[], ARRAY['Decide the target before the swing — the contact point and racket face angle create the direction.','Cross: slightly earlier contact point, racket face open cross-court.','Line: slightly later contact point, block or redirect along the line.','Body: aim for the server''s hip position — slightly inside the center of the service box.','Match the target to the serve: a wide serve naturally invites the cross-court return.']::text[], ARRAY['Deciding the target after the swing starts — always too late.','Over-aiming — reducing the effective target area by aiming right at the cone.','Using the same return direction regardless of the call — not responding to the target.']::text[], ARRAY['Player 2 does not call the zone — Player 1 must choose based on the serve placement.','Full points after the return: the called zone determines the starting tactical position.','Track the data: which zone does Player 1 hit most accurately? Focus extra reps there.']::text[], ARRAY['return','placement','target zones','intermediate','accuracy','deliberate']::text[], 'json', '{"p1":{"x":280,"y":60},"p2":{"x":240,"y":860},"shots":[{"x1":240,"y1":850,"x2":310,"y2":385},{"x1":280,"y1":65,"x2":110,"y2":820},{"x1":280,"y1":65,"x2":295,"y2":820},{"x1":280,"y1":65,"x2":200,"y2":820}],"cones":[{"x":110,"y":820},{"x":295,"y":820},{"x":200,"y":820}]}'::jsonb),
  ('RT-022', 'Return at Deuce: High Pressure Point Practice', 'Return', 'Mental', 'return', 'advanced', 15, 2, 'pairs', 'Train the return specifically under the pressure of deuce — the highest-leverage point in any game. Most players'' return quality changes at deuce: they become more conservative, more tense, or more erratic. This drill isolates the deuce return, provides concentrated repetitions at this exact score, and builds immunity to the tension that normally degrades return quality at high-pressure moments.', 'Train the return specifically under the pressure of deuce — the highest-leverage point in any game. Most players'' return quality changes at deuce: they become more conservative, more tense, or more erratic. This drill isolates the deuce return, provides concentrated repetitions at this exact score, and builds immunity to the tension that normally degrades return quality at high-pressure moments.', 'Every point begins at deuce. Player 2 serves from both courts. Player 1 returns. Both players play out each point. The deuce score is reset after every point — every single return is at deuce pressure.', ARRAY['Start every point at deuce. Player 2 serves from the deuce court.','Player 1 returns — maintaining exactly the same technique as in non-pressure situations.','Play out the full point.','Reset to deuce and repeat immediately.','Play 20 deuce points from the deuce court, then 20 from the ad court. Track: return quality, wins and losses.']::text[], ARRAY['The ball doesn''t know the score — the return technique must be identical at deuce.','Slow your breathing before the return — one exhale before the ball toss resets the nervous system.','Commit to a return target before the serve — indecision causes more errors than bad technique.','Notice if your swing gets shorter at deuce — shortening the swing is the most common pressure response.','After a missed return at deuce, reset with ''next point'' — never carry one mistake into the next.']::text[], ARRAY['Shortening the backswing under pressure — produces a blocked, weak return.','Aiming more conservatively — landing the return short and giving the server an easy point.','Rushing the return motion — faster does not mean better under pressure.']::text[], ARRAY['Ad-out practice: start every point at ad-out — one of the most pressured return situations.','Win streak: Player 1 must win 3 consecutive deuce returns to win the drill round.','Track consistency: compare return quality at 0-0 vs deuce — the numbers reveal the mental impact.']::text[], ARRAY['return','deuce','pressure','mental','advanced','match-simulation']::text[], 'json', '{"p1":{"x":280,"y":60},"p2":{"x":240,"y":860},"shots":[{"x1":240,"y1":850,"x2":310,"y2":385},{"x1":280,"y1":65,"x2":110,"y2":820},{"x1":240,"y1":855,"x2":200,"y2":382},{"x1":280,"y1":65,"x2":295,"y2":820}],"areas":[{"x":110,"y":820,"r":28},{"x":295,"y":820,"r":28}]}'::jsonb),
  ('RT-023', 'First Serve Return Percentage Tracking', 'Return', 'Assessment', 'return', 'beginner', 15, 2, 'pairs', 'Measure the baseline first serve return percentage and identify the most common error types. Most players have no idea what their actual first serve return percentage is. This data is essential: a 40% first serve return means the server wins the remaining 60% of points before the rally even starts. This drill creates the baseline measurement from which all return improvement is tracked.', 'Measure the baseline first serve return percentage and identify the most common error types. Most players have no idea what their actual first serve return percentage is. This data is essential: a 40% first serve return means the server wins the remaining 60% of points before the rally even starts. This drill creates the baseline measurement from which all return improvement is tracked.', 'Player 2 serves first serves from both courts at full pace. Player 1 tracks every return: in, into the net, or wide — and notes the approximate serve location. After 30 serves, calculate the first serve return percentage.', ARRAY['Player 2 serves 15 first serves from the deuce court at full pace.','Player 1 returns and a third person (or Player 2 on the next ball) records: in, net, or wide.','After 15 deuce serves, switch to 15 ad court serves.','Calculate overall percentage: returns in / 30 total serves.','Identify the most common error type (net vs wide) — this points to the technical correction needed.']::text[], ARRAY['Net errors: contact is too late or racket face is too closed — open the face slightly.','Wide errors: swing path is too cross-body — keep the swing more neutral.','Low in-percentage: the backswing may be too large for the serve speed.','High in-percentage with short returns: can afford more aggression.','Use this data weekly — track how the percentage improves with targeted practice.']::text[], ARRAY['Not tracking honestly — every return must be recorded accurately.','Serving too slowly — the data must reflect real first serve pace.','Only tracking the in/out result — fault type (net vs wide) is equally important.']::text[], ARRAY['Second serve tracking: compare first serve return % to second serve return %.','Deuce vs ad comparison: which court is the weaker return side?','Weekly measurement: track the percentage every week for one month — measure improvement.']::text[], ARRAY['return','tracking','percentage','beginner','assessment','data']::text[], 'json', '{"p1":{"x":200,"y":60},"p2":{"x":200,"y":860},"shots":[{"x1":240,"y1":855,"x2":310,"y2":385},{"x1":160,"y1":855,"x2":80,"y2":388},{"x1":200,"y1":60,"x2":110,"y2":820}],"cones":[{"x":310,"y":385},{"x":80,"y":388}]}'::jsonb),
  ('RT-024', 'Return Anticipation: Moving Before the Serve', 'Return', 'Reading', 'return', 'advanced', 12, 2, 'pairs', 'Train early anticipation on the return — moving before the ball is actually struck based on pre-contact cues from the server. Elite returners like Djokovic and Agassi start moving before the ball leaves the racket because they read the serve direction from the toss, shoulder angle, and swing path. Even partial anticipation dramatically improves return quality by giving the feet a head start.', 'Train early anticipation on the return — moving before the ball is actually struck based on pre-contact cues from the server. Elite returners like Djokovic and Agassi start moving before the ball leaves the racket because they read the serve direction from the toss, shoulder angle, and swing path. Even partial anticipation dramatically improves return quality by giving the feet a head start.', 'Player 2 serves from both courts. Player 1 must begin moving toward the expected serve direction before the ball makes contact with the racket — based purely on pre-contact cues. Player 2 confirms the location after each serve to verify whether the anticipation was correct.', ARRAY['Player 2 serves to random locations without declaring.','Player 1 must begin the first step of movement before the racket contacts the ball.','Player 2 confirms after each serve: was Player 1 moving in the right direction?','Track: what percentage of early reads are correct? Target: 55%+ correct.','Play 30 serves. Compare return quality when early read is correct vs incorrect.']::text[], ARRAY['Watch the toss arm direction and height — the toss is the earliest indicator of serve direction.','Watch the server''s ball-side shoulder: if it opens early, usually a slice wide.','Watch the point of contact: very high contact = kick, middle height = flat, lower = slice.','A wrong early read is recoverable — but a late reaction never is.','You only need to be correct 55% of the time to gain a massive advantage over pure reaction.']::text[], ARRAY['Moving too aggressively too early — committed fully to wrong direction with no ability to recover.','Not reading anything — waiting to react after contact rather than anticipating.','Reading correctly but not trusting the read — hesitating despite the correct read.']::text[], ARRAY['Exaggerated anticipation: Player 1 must take 2 full steps before contact — very aggressive.','Video comparison: film 10 returns with anticipation and 10 without — compare arrival time.','Reading accuracy chart: track which pre-contact cues Player 1 reads most accurately.']::text[], ARRAY['return','anticipation','reading','advanced','pre-contact','early movement']::text[], 'json', '{"p1":{"x":260,"y":60},"p2":{"x":240,"y":860},"moves":[{"x1":280,"y1":60,"x2":260,"y2":60}],"shots":[{"x1":240,"y1":850,"x2":310,"y2":385},{"x1":260,"y1":65,"x2":110,"y2":820}],"areas":[{"x":110,"y":820,"r":30}]}'::jsonb),
  ('RT-025', 'Return After a Long Rally: Fatigue Return', 'Return', 'Mental', 'return', 'advanced', 15, 2, 'pairs', 'Train the return under physical fatigue — the most honest test of return quality. In matches, the first return of each game often comes after 20-30 seconds of rest, but the return at the end of a close set comes after 10+ physically demanding rallies. This drill replicates that fatigue by requiring Player 1 to run before every return, then maintaining return quality despite being out of breath.', 'Train the return under physical fatigue — the most honest test of return quality. In matches, the first return of each game often comes after 20-30 seconds of rest, but the return at the end of a close set comes after 10+ physically demanding rallies. This drill replicates that fatigue by requiring Player 1 to run before every return, then maintaining return quality despite being out of breath.', 'Player 1 sprints from the net to the baseline before every serve. Player 2 serves the moment Player 1''s foot touches the baseline. Player 1 must return despite being out of breath from the sprint.', ARRAY['Player 1 starts at the net.','Player 1 sprints to the baseline at full speed.','The moment Player 1''s foot touches the baseline, Player 2 serves.','Player 1 must return despite being fatigued from the sprint.','Repeat 12 times per set. Rest 2 minutes. Play 3 sets. Track return quality under fatigue.']::text[], ARRAY['Control your breathing — exhale on the return contact, don''t hold your breath.','Even when fatigued, maintain the split step — the fatigue will tempt you to skip it.','Under fatigue, go for a neutral deep return — this is not the time for aggression.','Keep the swing compact when fatigued — shorter but still committed.','The returner who maintains quality under fatigue wins the final games of tight sets.']::text[], ARRAY['Not sprinting hard enough — the drill must genuinely replicate fatigue.','Completely losing technique under fatigue — some degradation is expected, complete collapse is not.','Skipping the split step because tired — this is exactly when it matters most.']::text[], ARRAY['Side-to-side sprint: Player 1 sprints sideline to sideline before the return — different fatigue pattern.','Fitness return set: play a full set with Player 1 sprinting before every return.','Track the fatigue effect: compare return quality in set 1 vs set 3 — fatigue compounds.']::text[], ARRAY['return','fatigue','mental','advanced','fitness','pressure']::text[], 'json', '{"p1":{"x":280,"y":60},"p2":{"x":240,"y":860},"moves":[{"x1":280,"y1":480,"x2":280,"y2":60}],"shots":[{"x1":240,"y1":850,"x2":310,"y2":385},{"x1":280,"y1":65,"x2":110,"y2":820}],"areas":[{"x":110,"y":820,"r":30}]}'::jsonb),
  ('RT-026', 'Forehand Return: Run Around the Backhand', 'Return', 'Tactical', 'return', 'advanced', 12, 2, 'pairs', 'Develop the run-around forehand return — moving around the backhand to hit a forehand return on a serve aimed to the backhand side. This is one of the most aggressive and effective return tactics against slow or moderate second serves. Running around to use the stronger forehand puts immediate offensive pressure on the server and sets up the inside-out forehand pattern.', 'Develop the run-around forehand return — moving around the backhand to hit a forehand return on a serve aimed to the backhand side. This is one of the most aggressive and effective return tactics against slow or moderate second serves. Running around to use the stronger forehand puts immediate offensive pressure on the server and sets up the inside-out forehand pattern.', 'Player 2 serves moderate second serves to Player 1''s backhand side. Player 1 must run around the backhand and return with the forehand. After the run-around forehand return, Player 1 plays out the point.', ARRAY['Player 2 serves moderate second serves to Player 1''s backhand — from both courts.','Player 1 runs around the backhand and hits a forehand return.','The forehand return goes inside-out (cross-court from Player 1''s backhand position).','Play out the full point after the run-around forehand.','Repeat 15 times from each court. Track: how many run-around forehands land in the target?']::text[], ARRAY['Read the second serve early — the run-around must begin before the ball bounces.','Get completely around the ball — don''t half-run-around and hit a compromised shot.','The inside-out forehand goes to the ad side from deuce court — or deuce side from ad court.','After the run-around return, recover to center — the DTL is now open.','Only run-around if you have enough time — a late run-around produces a rushed, weak shot.']::text[], ARRAY['Running around on a fast serve — not enough time, produces a total miss.','Half-running-around — ending up hitting a compromised forehand from the wrong position.','Not recovering after the run-around — DTL is completely open.']::text[], ARRAY['Run-around plus inside-in: after running around, go inside-in instead of inside-out.','Run-around return competition: Player 2 tries to serve fast enough that Player 1 cannot run around.','First serve run-around: Player 1 attempts the run-around on first serves — extreme aggression.']::text[], ARRAY['return','run-around','forehand','advanced','second serve','aggressive']::text[], 'json', '{"p1":{"x":120,"y":60},"p2":{"x":160,"y":860},"moves":[{"x1":280,"y1":60,"x2":120,"y2":60}],"shots":[{"x1":160,"y1":850,"x2":250,"y2":388},{"x1":120,"y1":65,"x2":295,"y2":830}],"areas":[{"x":295,"y":830,"r":28}]}'::jsonb),
  ('RT-027', 'Return Pattern: Cross then DTL', 'Return', 'Tactical', 'return', 'intermediate', 12, 2, 'pairs', 'Develop the two-serve return pattern — returning cross-court consistently for several serves to establish a pattern, then redirecting down-the-line to surprise the server who has started to anticipate the cross-court. Pattern play on the return is an advanced tactical skill that transforms the return from a reactive shot into a proactive point-construction tool.', 'Develop the two-serve return pattern — returning cross-court consistently for several serves to establish a pattern, then redirecting down-the-line to surprise the server who has started to anticipate the cross-court. Pattern play on the return is an advanced tactical skill that transforms the return from a reactive shot into a proactive point-construction tool.', 'Player 2 serves from the deuce court. Player 1 returns cross-court for 3 serves in a row, then redirects DTL on the 4th. Player 2 is told to anticipate the cross-court on the 4th serve — replicating how a smart server begins to cheat after seeing a pattern.', ARRAY['Player 2 serves 3 balls — Player 1 returns all 3 cross-court.','Player 2 announces they are anticipating cross-court on the 4th serve.','Player 2 serves the 4th — Player 1 goes DTL.','Play out each point fully after the return.','Repeat 8 four-serve sequences. Track: how many DTL redirects catch Player 2 cheating?']::text[], ARRAY['Build the pattern first: 3 consecutive cross-court returns is enough to create expectation.','Watch the server start to lean: when they cheat to the cross-court, pull the trigger DTL.','The DTL on the 4th return should look identical to the first 3 in preparation.','After going DTL, immediately return to the cross-court pattern — reset the sequence.','The pattern only works if the cross-court returns are genuinely good — weak pattern balls give nothing.']::text[], ARRAY['Going DTL too early — one or two cross-courts are not enough to establish a pattern.','Going DTL from a wide position — the pattern must be set up from a neutral position.','DTL with different preparation — telegraphed to a smart server who reads the switch.']::text[], ARRAY['Two-cross then DTL: shorter pattern, more frequent DTL — for aggressive returners.','Four-cross then DTL: longer pattern, maximum expectation before the surprise.','Player 2 is allowed to react: after the cross pattern, Player 2 can cover either side — tests disguise quality.']::text[], ARRAY['return','pattern','cross-court','DTL','intermediate','tactical']::text[], 'json', '{"p1":{"x":280,"y":60},"p2":{"x":240,"y":860},"shots":[{"x1":240,"y1":850,"x2":310,"y2":385},{"x1":280,"y1":65,"x2":110,"y2":820},{"x1":280,"y1":65,"x2":295,"y2":820}],"areas":[{"x":110,"y":820,"r":25},{"x":295,"y":820,"r":25}]}'::jsonb),
  ('RT-028', 'Return and Win: Second Serve Game', 'Return', 'Match Simulation', 'return', 'intermediate', 15, 2, 'pairs', 'Train the complete second serve return game — playing points starting from a second serve situation. The second serve return game is where the returner should have a significant advantage, but most players fail to exploit this advantage because they return passively. This drill creates explicit pressure to attack second serves and win the majority of these points.', 'Train the complete second serve return game — playing points starting from a second serve situation. The second serve return game is where the returner should have a significant advantage, but most players fail to exploit this advantage because they return passively. This drill creates explicit pressure to attack second serves and win the majority of these points.', 'Player 2 serves only second serves from both courts. Player 1 returns. Both players play out full points. Player 1 wins the drill by winning more than 50% of these points — anything less means the second serve return game is not being exploited.', ARRAY['Player 2 serves only second serves — kick or slice.','Player 1 returns aggressively and plays out the full point.','Track: how many second serve return points does Player 1 win?','Play 20 second serve return points from each court.','Target: Player 1 wins 55%+ from each court.']::text[], ARRAY['On second serves, Player 1 should always be the aggressor — not the defender.','Step inside the baseline on every second serve — claim the court.','Drive the return — a chip or block gives the server an easy rally ball.','After the aggressive return, be ready to continue attacking — the server is on defense.','If Player 1 is winning less than 50%, they are returning too passively — be more aggressive.']::text[], ARRAY['Returning second serves as if they were first serves — conservative when aggression is warranted.','Chip returning weak second serves — leaving a free attack opportunity on the table.','Winning the return but losing the rally — the attack must continue past the first ball.']::text[], ARRAY['Only first serve: now compare to first serve points — the ratio reveals return effectiveness.','Handicap: Player 1 starts each second serve return point at 30-0 — but must still win.','Return game set: play a full set with only second serves — tests extended second serve return quality.']::text[], ARRAY['return','second serve','match-simulation','intermediate','aggressive','win rate']::text[], 'json', '{"p1":{"x":280,"y":90},"p2":{"x":240,"y":860},"moves":[{"x1":280,"y1":60,"x2":280,"y2":90}],"shots":[{"x1":240,"y1":850,"x2":220,"y2":388},{"x1":280,"y1":90,"x2":100,"y2":820},{"x1":100,"y1":830,"x2":295,"y2":100}],"areas":[{"x":100,"y":820,"r":30}]}'::jsonb),
  ('RT-029', 'Return Wide Serve Ad Court: Backhand Stretch', 'Return', 'Technique', 'return', 'intermediate', 10, 2, 'pairs', 'Train the return of the wide serve to the ad court backhand — the serve that most commonly forces an error or a weak return from right-handed players. The wide ad serve pulls the returner off the court to their backhand side, which already feels uncomfortable for most players, and then forces a return from a stretched, off-balance position. This drill trains both the movement and the compact return motion needed from this specific position.', 'Train the return of the wide serve to the ad court backhand — the serve that most commonly forces an error or a weak return from right-handed players. The wide ad serve pulls the returner off the court to their backhand side, which already feels uncomfortable for most players, and then forces a return from a stretched, off-balance position. This drill trains both the movement and the compact return motion needed from this specific position.', 'Player 2 serves wide slice serves from the ad court — pulling Player 1''s backhand far outside the singles sideline. Player 1 must chase the wide serve and return it cross-court.', ARRAY['Player 2 serves wide slice serves from the ad court.','Player 1 must sprint wide, reaching the ball before the second bounce.','Player 1 chips or drives the return cross-court — to the deuce side.','Player 1 recovers to the center after the return.','Repeat 15 times. Track: what percentage does Player 1 successfully return? Target: 70%.']::text[], ARRAY['Quick first step laterally — the wide ad serve moves away from the body quickly.','From a stretched position, use a compact chip return — there is no time for a drive.','Cross-court is the only viable option from a wide backhand position.','Plant the outside foot and rotate — open stance backhand from wide.','After the return, sprint back toward center — don''t stay wide.']::text[], ARRAY['Going DTL from a stretched backhand position — extremely high risk, usually goes wide.','Taking a full backswing from the wide position — no time, produces a late mis-hit.','Not recovering to center — second ball catches Player 1 still wide.']::text[], ARRAY['Wide ad return then recovery rally: after the wide return, Player 2 hits to the center — Player 1 must get there.','Wide ad consistency: 8 of 10 wide ad backhands must land cross-court past the service line.','Chip and charge from wide: chip the wide ad return and follow to the net.']::text[], ARRAY['return','wide serve','ad court','backhand','intermediate','stretch']::text[], 'json', '{"p1":{"x":65,"y":60},"p2":{"x":160,"y":860},"moves":[{"x1":120,"y1":60,"x2":65,"y2":60}],"shots":[{"x1":160,"y1":850,"x2":80,"y2":388},{"x1":65,"y1":65,"x2":295,"y2":820}],"areas":[{"x":295,"y":820,"r":30}]}'::jsonb),
  ('RT-030', 'Return Game Intelligence: Tracking Server Patterns', 'Return', 'Tactical', 'return', 'advanced', 15, 2, 'pairs', 'Develop the habit of tracking server patterns during a match — identifying tendencies and using that information to improve return positioning and anticipation over time. Elite returners keep a mental database of what the server likes to do at deuce, at ad-out, on first serves, and on second serves. This drill makes that tracking explicit and trains the habit of using patterns as a tactical weapon.', 'Develop the habit of tracking server patterns during a match — identifying tendencies and using that information to improve return positioning and anticipation over time. Elite returners keep a mental database of what the server likes to do at deuce, at ad-out, on first serves, and on second serves. This drill makes that tracking explicit and trains the habit of using patterns as a tactical weapon.', 'Player 2 serves a full game from both courts. Player 1 returns and a third person (or Player 1 themselves in between points) tracks every serve location and type. After every 5 serves, Player 1 identifies the pattern and adjusts position.', ARRAY['Player 2 serves a game (at least 8 serves) from the deuce court.','Player 1 or a third person records every serve: location (T/wide/body), type (flat/kick/slice), and court (deuce/ad).','After 8 serves, Player 1 identifies the most common serve location.','Player 1 adjusts return position to favor the most common location on the next 5 serves.','Track: does the position adjustment improve return success rate?']::text[], ARRAY['Most servers have tendencies: they serve to the same location at deuce, same at ad-out.','Watch for patterns in pressure moments: where does this server go at 30-40?','After identifying a pattern, cheat slightly — don''t completely abandon the other side.','Track serve patterns in every warm-up — 10 warm-up serves reveal enormous information.','A returner who tracks patterns is always one step ahead of the server.']::text[], ARRAY['Not tracking at all — returning reactively without any pattern awareness.','Over-cheating after identifying a pattern — gives up the other direction entirely.','Forgetting the pattern after one exception — servers revert to their tendencies under pressure.']::text[], ARRAY['Pattern notebook: Player 1 physically writes down serve patterns during changeovers.','Pattern test: Player 2 intentionally follows a set pattern — how quickly does Player 1 identify it?','Pattern exploitation: once identified, track how many extra points the pattern awareness generates.']::text[], ARRAY['return','patterns','tracking','advanced','tactical','intelligence']::text[], 'json', '{"p1":{"x":280,"y":60},"p2":{"x":240,"y":860},"shots":[{"x1":240,"y1":850,"x2":200,"y2":378},{"x1":240,"y1":850,"x2":318,"y2":388},{"x1":240,"y1":850,"x2":152,"y2":382}],"cones":[{"x":200,"y":378},{"x":318,"y":388}],"areas":[{"x":318,"y":388,"r":30}]}'::jsonb),
  ('RT-031', 'Return at Net: Attacking the Second Serve and Charging', 'Return', 'Tactical', 'return', 'advanced', 12, 2, 'pairs', 'Develop the return plus net rush pattern — attacking the second serve with a drive return and immediately following it to the net. This is one of the most aggressive tactics in tennis: the server expects the returner to stay back, but instead the returner drives the return deep and follows it to take the net away from the server. Used correctly, it creates immediate pressure and forces the server to make a passing shot from behind the baseline.', 'Develop the return plus net rush pattern — attacking the second serve with a drive return and immediately following it to the net. This is one of the most aggressive tactics in tennis: the server expects the returner to stay back, but instead the returner drives the return deep and follows it to take the net away from the server. Used correctly, it creates immediate pressure and forces the server to make a passing shot from behind the baseline.', 'Player 2 serves only second serves. Player 1 drives the return aggressively and follows it immediately to the net. Player 2 attempts a passing shot or lob — Player 1 volleys the finish.', ARRAY['Player 2 serves a second serve from the deuce court.','Player 1 drives the return aggressively and immediately sprints to the net.','Player 2 attempts a passing shot or lob.','Player 1 split steps and finishes with a volley or overhead.','Repeat 15 times from each court. Track: percentage of return-and-rush points won.']::text[], ARRAY['The return must be deep — a short return stops you from advancing safely.','Move to the net the moment the return leaves the racket — no hesitation.','Sprint diagonally toward the center of the net — not straight ahead.','Split step as Player 2 contacts the passing shot — always, even mid-sprint.','The server is often caught off guard — this pattern wins points even when executed imperfectly.']::text[], ARRAY['Drive return not deep enough — Player 2 has an easy passing shot from inside the baseline.','Stopping after the return instead of following to the net.','No split step — cannot volley or overhead without it.']::text[], ARRAY['Chip and charge on first serves: same pattern but with a chip on first serves.','Return plus net rush competition: track over 20 attempts — what percentage wins?','Doubles return plus charge: return deep and both players rush the net — full doubles pattern.']::text[], ARRAY['return','net rush','aggressive','advanced','tactical','second serve']::text[], 'json', '{"p1":{"x":280,"y":550},"p2":{"x":240,"y":860},"moves":[{"x1":280,"y1":60,"x2":280,"y2":100},{"x1":280,"y1":100,"x2":280,"y2":550}],"shots":[{"x1":240,"y1":850,"x2":220,"y2":388},{"x1":280,"y1":100,"x2":100,"y2":820},{"x1":240,"y1":870,"x2":240,"y2":630},{"x1":278,"y1":545,"x2":100,"y2":120}],"areas":[{"x":100,"y":820,"r":28}]}'::jsonb),
  ('RT-032', 'Slow Serve Return: Building Patience', 'Return', 'Mental', 'return', 'beginner', 10, 2, 'pairs', 'Train the return of slow serves — a surprisingly common challenge that many players handle poorly. Against a slow server, the ball takes longer to arrive, which causes impatience, early eye movement, and mistiming. Many players actually return slow serves worse than fast ones because they overthink, overhit, or simply lose rhythm waiting for the ball. This drill builds patience and a controlled response to slow serves.', 'Train the return of slow serves — a surprisingly common challenge that many players handle poorly. Against a slow server, the ball takes longer to arrive, which causes impatience, early eye movement, and mistiming. Many players actually return slow serves worse than fast ones because they overthink, overhit, or simply lose rhythm waiting for the ball. This drill builds patience and a controlled response to slow serves.', 'Player 2 serves very slow serves — 30-40% of normal pace. Player 1 must wait patiently for the ball, take it at the correct contact point, and return it deep and consistently. The temptation to overhit must be consciously resisted.', ARRAY['Player 2 serves very slow serves from the deuce court.','Player 1 must wait for the ball — no rushing the swing.','Player 1 drives the return deep but controlled — not overhitting.','Target: return landing in the back half of the court.','Repeat 15 slow serve returns from each court. Track: consistency and depth.']::text[], ARRAY['Wait for the ball — let it come to your ideal contact zone, don''t lunge at it.','Slow servers tempt players to overhit — resist the urge. Control is the goal.','Take a full backswing — you have the time on slow serves.','Aim for depth, not power — a deep, controlled return wins more points than an overhit error.','Eyes on the ball longer than normal — the extra time in the air makes eye tracking easier.']::text[], ARRAY['Rushing the swing because the ball takes too long — produces early contact and errors.','Overhitting the slow serve — giving away a free point.','Losing focus because of the slow pace — the mind wanders during the ball''s flight.']::text[], ARRAY['Drop shot return: against a very slow serve, Player 1 returns with a drop shot.','Mix slow and normal: Player 2 alternates slow and normal serves — Player 1 must adjust each time.','Placement on slow serves: Player 1 must hit all four corners in rotation — uses the extra time productively.']::text[], ARRAY['return','slow serve','patience','beginner','mental','timing']::text[], 'json', '{"p1":{"x":280,"y":60},"p2":{"x":240,"y":860},"shots":[{"x1":240,"y1":850,"x2":310,"y2":388},{"x1":280,"y1":65,"x2":110,"y2":820}],"areas":[{"x":110,"y":820,"r":40}]}'::jsonb),
  ('RT-033', 'Return Game Full Set: First Serve Only', 'Return', 'Match Simulation', 'return', 'advanced', 20, 2, 'pairs', 'Train the return game under full match conditions using only first serves — the hardest return scenario. A full set where every point starts with a first serve forces Player 1 to solve the most difficult return challenge repeatedly across many points. Tracking performance across a full set reveals patterns, fatigue effects, and tactical tendencies that shorter drills cannot expose.', 'Train the return game under full match conditions using only first serves — the hardest return scenario. A full set where every point starts with a first serve forces Player 1 to solve the most difficult return challenge repeatedly across many points. Tracking performance across a full set reveals patterns, fatigue effects, and tactical tendencies that shorter drills cannot expose.', 'Player 2 serves only first serves from both courts — no second serves. Player 1 returns and both players play out full points. Play a full set (first to 6, win by 2). Both players track: return in-percentage, return depth, and points won after successful returns.', ARRAY['Play a full practice set. Player 2 serves only first serves — no second serves allowed.','If Player 1 misses the return, the point goes to Player 2 (simulates an ace or return error).','If Player 1 returns successfully, play the full point out.','Track every game: Player 1''s return in-percentage and whether points were won after the return.','After the set, review: which serves were hardest? Which return patterns worked? What tactical adjustments are needed?']::text[], ARRAY['Treat every point identically — no letting up on important points or unimportant ones.','Identify which specific serves you struggled with and note them for practice.','Track whether your return quality changed in the second half of the set — fatigue reveals itself.','After the set, ask: did you return as aggressively on second serves as you planned? Probably not.','The full set reveals the gap between practice return quality and match return quality.']::text[], ARRAY['Becoming more conservative as the set progresses — the opposite of what is needed.','Not tracking data — the set is also an assessment tool, not just a competition.','Not adjusting based on what is working — smart players adapt within a set.']::text[], ARRAY['Second serve full set: play the same set but now Player 2 serves only second serves — compare.','Mixed set: odd games first serves only, even games second serves only — variety.','Track 3 sets: play 3 full sets and compare return statistics across all 3.']::text[], ARRAY['return','match-simulation','full set','advanced','assessment','first serve']::text[], 'json', '{"p1":{"x":200,"y":60},"p2":{"x":200,"y":860},"shots":[{"x1":240,"y1":855,"x2":310,"y2":385},{"x1":160,"y1":855,"x2":80,"y2":388},{"x1":200,"y1":60,"x2":110,"y2":820},{"x1":200,"y1":60,"x2":290,"y2":820}],"areas":[{"x":110,"y":820,"r":25},{"x":290,"y":820,"r":25}]}'::jsonb),
  ('RT-034', 'Return Disguise: Same Setup, Two Directions', 'Return', 'Tactical', 'return', 'advanced', 12, 2, 'pairs', 'Train return disguise — using the same preparation and setup for both cross-court and down-the-line returns so the server cannot read the direction before the ball is hit. Return disguise is an advanced skill that requires isolating the direction change to the contact point rather than the swing path. When a returner can disguise direction, the server cannot cheat to cover the most likely return.', 'Train return disguise — using the same preparation and setup for both cross-court and down-the-line returns so the server cannot read the direction before the ball is hit. Return disguise is an advanced skill that requires isolating the direction change to the contact point rather than the swing path. When a returner can disguise direction, the server cannot cheat to cover the most likely return.', 'Player 2 serves from the deuce court. Player 2 tries to guess whether the return will go cross-court or down-the-line before the ball lands. Player 1 must go the opposite direction of the guess — using identical preparation for both.', ARRAY['Player 2 serves from the deuce court.','Player 2 calls ''cross'' or ''line'' as Player 1 begins to swing.','Player 1 must go the opposite direction — using the same preparation for both.','Score: +1 for Player 1 if they go the opposite direction. +1 for Player 2 if Player 1 cannot redirect in time.','First to 10 wins. Switch roles.']::text[], ARRAY['Identical backswing for both directions — the disguise must be complete from the first movement.','The direction difference happens only at the contact point — earlier than the contact is a tell.','Cross-court: contact slightly earlier, racket face opens cross-court.','DTL: contact slightly later, racket face stays more neutral.','The more natural-looking the preparation, the harder it is for the server to read.']::text[], ARRAY['Different setup for each direction — immediately readable even to untrained observers.','Not being able to change direction in time — needs more deliberate practice of the contact point difference.','Always going cross-court when Player 2 calls ''line'' — lack of reliable DTL return.']::text[], ARRAY['Add a third direction: body return — Player 2 can now call ''cross'', ''line'', or ''body''.','Random serving: Player 2 serves to random locations — Player 1 must disguise from various positions.','Video analysis: film the returns and check if the preparation actually looks the same.']::text[], ARRAY['return','disguise','advanced','direction','tactical','contact point']::text[], 'json', '{"p1":{"x":280,"y":60},"p2":{"x":240,"y":860},"shots":[{"x1":240,"y1":850,"x2":310,"y2":385},{"x1":280,"y1":65,"x2":110,"y2":820},{"x1":280,"y1":65,"x2":295,"y2":820}],"areas":[{"x":110,"y":820,"r":25},{"x":295,"y":820,"r":25}]}'::jsonb),
  ('RT-035', 'Return Grand Finale: Full Return Game Assessment', 'Return', 'Assessment', 'return', 'intermediate', 20, 2, 'pairs', 'Synthesize all return skills in a comprehensive match-style assessment that covers every aspect of the return game. This final drill measures: first serve return percentage, second serve attack rate, placement accuracy, reading accuracy, and win rate. It generates a complete return game profile that identifies the highest-priority areas for future practice.', 'Synthesize all return skills in a comprehensive match-style assessment that covers every aspect of the return game. This final drill measures: first serve return percentage, second serve attack rate, placement accuracy, reading accuracy, and win rate. It generates a complete return game profile that identifies the highest-priority areas for future practice.', 'Player 2 serves a full practice set from both courts using first and second serves. A third person (or both players alternating) tracks all return data comprehensively. After the set, both players review all tracked data and identify the top 2 return priorities for the next training block.', ARRAY['Play a full practice set using normal serving (first and second serves).','Track every return: court (deuce/ad), serve type (flat/kick/slice), serve location (T/wide/body), return direction, return depth, and point outcome.','After the set, calculate: first serve return %, second serve return %, return win rate.','Identify the 2 most common return errors and the 2 most successful patterns.','Create a specific practice plan for the next session based on the data.']::text[], ARRAY['Play your natural game — the assessment only works with authentic play.','First serve return % should be 55%+ for competitive players, 65%+ for advanced.','Second serve return win % should be above 50% — if not, you are returning too passively.','Most common error: net errors suggest closed face or late contact. Wide errors suggest rushing.','The data reveals the gap between perceived return quality and actual return quality.']::text[], ARRAY['Playing differently because of tracking — defeats the purpose of the assessment.','Not using the data to drive practice — collecting data without acting on it is worthless.','Only tracking outcomes — process data (placement, depth) is more actionable than just wins/losses.']::text[], ARRAY['Video assessment: film the full set and review alongside the tracking data.','Three-set assessment: track all three sets and compare to see how return quality changes.','Peer assessment: both players assess each other''s return data and provide specific feedback.']::text[], ARRAY['return','assessment','match-simulation','intermediate','comprehensive','data']::text[], 'json', '{"p1":{"x":200,"y":60},"p2":{"x":200,"y":860},"shots":[{"x1":240,"y1":855,"x2":310,"y2":385},{"x1":200,"y1":60,"x2":110,"y2":820},{"x1":160,"y1":855,"x2":80,"y2":388},{"x1":200,"y1":60,"x2":295,"y2":820},{"x1":200,"y1":60,"x2":200,"y2":820}],"cones":[{"x":110,"y":820},{"x":295,"y":820},{"x":200,"y":820}],"areas":[{"x":200,"y":810,"r":50}]}'::jsonb),
  ('SV-011', 'Flat Serve Power Progression', 'Serve', 'Flat', 'serve', 'intermediate', 12, 1, 'individual', 'Build maximum flat serve power through a progressive warm-up ladder. Most players try to serve at full power from the very first ball, which creates tension, reduces racket head speed, and ingrams a tight motion. This drill starts at 50% effort and builds to 100% over several rounds, allowing the body to open up naturally and find maximum pace through a relaxed, fluid motion rather than forced muscle.', 'Build maximum flat serve power through a progressive warm-up ladder. Most players try to serve at full power from the very first ball, which creates tension, reduces racket head speed, and ingrams a tight motion. This drill starts at 50% effort and builds to 100% over several rounds, allowing the body to open up naturally and find maximum pace through a relaxed, fluid motion rather than forced muscle.', 'Player 1 serves from the deuce court baseline using a full basket of balls. No returner needed. Focus is purely on building pace progressively through a relaxed kinetic chain.', ARRAY['Round 1: Serve 5 balls at 50% effort — smooth, relaxed, full motion but no pace.','Round 2: Serve 5 balls at 70% effort — add leg drive, keep the arm loose.','Round 3: Serve 5 balls at 85% effort — full pronation, snap through the ball.','Round 4: Serve 5 balls at 100% effort — maximum leg drive, full hip rotation, arm whip.','Rest 90 seconds between rounds. Track how many land in the service box at each level.']::text[], ARRAY['A relaxed arm moves faster than a tense one — looseness is the foundation of power.','Leg drive is the engine — at 100%, your heels should come completely off the ground.','Let the elbow lead on the way up — the racket head trails behind, creating a whip effect.','Pronate fully through contact — the racket face turns from tilted to facing forward.','Hold nothing back on Round 4 — swing through the ball as if trying to knock it through the fence.']::text[], ARRAY['Tensing the arm to generate more power — tension kills racket head speed.','Not using leg drive at higher effort levels — arm-only serves plateau quickly.','Short-arming the follow-through — stopping the swing before full completion kills pace.']::text[], ARRAY['Alternate between 50% and 100% every ball — teaches the feel of relaxed versus forced.','Add a returner at 100% round — tests if the power translates into actual unreturnable serves.','Measure with a speed gun or app — track the speed difference between rounds.']::text[], ARRAY['serve','flat','power','progression','intermediate','solo']::text[], 'json', '{"p1":{"x":240,"y":860},"shots":[{"x1":240,"y1":850,"x2":200,"y2":370},{"x1":240,"y1":850,"x2":315,"y2":390}],"areas":[{"x":200,"y":370,"r":25},{"x":315,"y":390,"r":25}]}'::jsonb),
  ('SV-012', 'Slice Serve: Deuce Court Wide Pull', 'Serve', 'Slice', 'serve', 'intermediate', 12, 2, 'pairs', 'Develop a wide slice serve from the deuce court that curves sharply and pulls the returner far outside the singles sideline. The wide deuce slice is the serve that opens the court most dramatically — when hit correctly, the returner is pulled 3-4 feet outside the sideline, leaving the entire deuce side completely open for the next shot. It is essential for right-handed servers on fast surfaces.', 'Develop a wide slice serve from the deuce court that curves sharply and pulls the returner far outside the singles sideline. The wide deuce slice is the serve that opens the court most dramatically — when hit correctly, the returner is pulled 3-4 feet outside the sideline, leaving the entire deuce side completely open for the next shot. It is essential for right-handed servers on fast surfaces.', 'Player 1 serves from the deuce court baseline. Player 2 stands in the normal deuce-court return position. Three cones mark how far outside the sideline Player 2 is pulled — 1 foot, 2 feet, and 3 feet outside. The goal is to pull Player 2 to the 3-foot cone.', ARRAY['Player 1 serves wide slice serves from the deuce court.','After each serve, Player 2 walks to the spot where they had to return from — marks it with a cone.','Track: is Player 2 being pulled 1 foot, 2 feet, or 3+ feet outside the sideline?','After 10 serves, play out the full point — Player 1 attacks the open deuce side on the plus-one.','Target: 7 out of 10 serves pulling Player 2 at least 2 feet outside the sideline.']::text[], ARRAY['Toss slightly to the right — further right than a T serve, which sets up the cross-body brush.','Contact the ball on the right side — at roughly 3 o''clock on the ball''s face.','Brush firmly across and around — don''t stab or push, sweep across with commitment.','Your follow-through goes left — the cross-body finish drives the rightward curve.','The wider the toss, the wider the serve — practice the toss separately to get the angle right.']::text[], ARRAY['Contacting the ball at 12 o''clock — produces a flat wide serve instead of a curving slice.','Follow-through going straight down — kills the horizontal spin.','Toss too far left — cannot get across the ball from that position.']::text[], ARRAY['Slice wide then inside-out forehand — the pull creates the perfect setup.','Mix with T serve — Player 2 must guess wide or T before the serve.','Speed test: maximum slice curve at 70% pace vs 90% — which creates more pull?']::text[], ARRAY['serve','slice','wide','deuce court','angle','intermediate']::text[], 'json', '{"p1":{"x":240,"y":860},"p2":{"x":290,"y":60},"shots":[{"x1":240,"y1":850,"x2":328,"y2":392}],"areas":[{"x":328,"y":392,"r":20}],"cones":[{"x":320,"y":392},{"x":335,"y":392},{"x":350,"y":392}]}'::jsonb),
  ('SV-013', 'Kick Serve Depth and Height Control', 'Serve', 'Kick', 'serve', 'advanced', 12, 2, 'pairs', 'Refine the kick serve specifically for depth and bounce height — the two qualities that make the kick serve truly difficult to return. A kick serve that lands short gives the returner time to step in and attack. A kick serve with no height gives the returner a comfortable mid-height ball. This drill trains both qualities simultaneously, producing a kick serve that lands deep and kicks above the returner''s shoulder.', 'Refine the kick serve specifically for depth and bounce height — the two qualities that make the kick serve truly difficult to return. A kick serve that lands short gives the returner time to step in and attack. A kick serve with no height gives the returner a comfortable mid-height ball. This drill trains both qualities simultaneously, producing a kick serve that lands deep and kicks above the returner''s shoulder.', 'Player 1 serves from both courts. Player 2 returns and calls out the bounce height after each serve: ''low'' (below waist), ''medium'' (waist to shoulder), or ''high'' (above shoulder). A cone marks the depth target — 3 feet inside the baseline of the service box.', ARRAY['Player 1 serves kick serves from the deuce court first.','Player 2 calls the bounce height after each serve — ''low'', ''medium'', or ''high''.','Player 1 also tracks whether each serve lands past the depth cone.','Score: +2 for ''high'' plus deep, +1 for ''medium'' plus deep, 0 for anything else.','Play 20 serves per court. Target: 25+ points on each court.']::text[], ARRAY['More topspin equals more height and more depth — both qualities come from the same motion.','Swing harder from 7 to 1 — more racket head speed through the spin zone means more kick.','Arch your back fully — the bigger the arch, the more your swing goes upward through the ball.','Snap your wrist completely at contact — the wrist snap is the final accelerator.','Land the serve in the back third of the service box — never short, always deep.']::text[], ARRAY['Kick serve landing short — not enough topspin to bring the ball down deep.','Kick bouncing low — not enough upward swing angle through the contact zone.','Inconsistent toss position — changes the ball contact point and ruins the kick.']::text[], ARRAY['Kick serve to body — same motion, different target — jams the returner on the hip at shoulder height.','Kick second serve challenge: must land 10 consecutive kick serves deep and ''high'' — no exceptions.','Kick to backhand from ad court: combine depth, height, and placement for a complete second serve.']::text[], ARRAY['serve','kick','depth','height','advanced','second serve']::text[], 'json', '{"p1":{"x":240,"y":860},"p2":{"x":150,"y":60},"shots":[{"x1":240,"y1":850,"x2":175,"y2":385}],"areas":[{"x":175,"y":385,"r":28}],"cones":[{"x":175,"y":355}]}'::jsonb),
  ('SV-014', 'Ad Court T Serve: Forehand Attacker', 'Serve', 'Flat', 'serve', 'intermediate', 10, 2, 'pairs', 'Develop the ad court T serve — aimed at the center service line from the ad side. This serve goes directly to the returner''s forehand but at an angle that eliminates their down-the-line return option. More importantly, it sets up the server''s forehand on the plus-one by drawing the return back through the center, where the server is already in position. It is the tactical mirror of the deuce court wide slice.', 'Develop the ad court T serve — aimed at the center service line from the ad side. This serve goes directly to the returner''s forehand but at an angle that eliminates their down-the-line return option. More importantly, it sets up the server''s forehand on the plus-one by drawing the return back through the center, where the server is already in position. It is the tactical mirror of the deuce court wide slice.', 'Player 1 serves from the ad court baseline. Player 2 stands in the ad court return position. Player 1 targets the T — the center service line of the deuce service box. A cone marks the target landing zone.', ARRAY['Player 1 serves flat or light-slice serves from the ad court to the T.','The serve should land within 1 foot of the center service line.','Player 2 returns — the return will likely come back through the center.','Player 1 attacks the plus-one with an aggressive forehand.','Track: how many T serves land in the target zone? Target: 7 out of 10.']::text[], ARRAY['Toss slightly to the left from the ad court — inside the baseline, toward the center.','From the ad court, T means going away from your body — you must drive across your body slightly.','Use flat or very light slice — heavy spin from the ad court sends the ball wide instead of T.','After serving, move right toward the center — position for the forehand plus-one.','The T serve from the ad court is often neglected — most players only serve wide from there.']::text[], ARRAY['Serve landing in the net — not enough pace to carry the ball to the back T from the ad side.','Serve going wide instead of T — too much leftward swing angle.','Not moving to position after the serve — caught behind on the plus-one forehand.']::text[], ARRAY['Ad court T then inside-in forehand: T serve draws returner in, inside-in finishes the point.','Mix ad T with ad wide: Player 2 must guess which side before the serve.','Second serve T: use a kick T from the ad court — extremely effective surprise second serve.']::text[], ARRAY['serve','flat','ad court','T serve','intermediate','pattern']::text[], 'json', '{"p1":{"x":160,"y":860},"p2":{"x":120,"y":60},"shots":[{"x1":160,"y1":850,"x2":200,"y2":385}],"areas":[{"x":200,"y":385,"r":22}],"cones":[{"x":200,"y":385}]}'::jsonb),
  ('SV-015', 'Second Serve: Kick vs. Slice Selection', 'Serve', 'Kick', 'serve', 'advanced', 15, 2, 'pairs', 'Train the deliberate selection between a kick second serve and a slice second serve depending on game context. The kick serve bounces high and is used against backhand returners and when more margin is needed. The slice second serve stays low and is used to prevent the returner from attacking, on fast surfaces, and as a surprise. Knowing when to use each — and being able to execute both — is an advanced server skill.', 'Train the deliberate selection between a kick second serve and a slice second serve depending on game context. The kick serve bounces high and is used against backhand returners and when more margin is needed. The slice second serve stays low and is used to prevent the returner from attacking, on fast surfaces, and as a surprise. Knowing when to use each — and being able to execute both — is an advanced server skill.', 'Player 1 serves second serves from both courts. Player 2 returns and calls ''kick'' or ''slice'' after each serve based on what they read from the spin. Player 1 must hit the intended serve type — mislabeling counts as an error.', ARRAY['Player 1 calls ''kick'' or ''slice'' before each second serve — commits to the type.','Player 2 identifies which type was hit based on the ball behavior and calls it out.','If Player 2''s call matches Player 1''s call — correct execution.','If they don''t match — Player 1 served the wrong type and counts as an error.','Play 20 second serves per set. Target: 17+ correct executions per set.']::text[], ARRAY['Kick: toss behind and to the left, swing 7 to 1, ball rises after bounce.','Slice: toss to the right, brush across the right side of the ball, ball stays low and curves.','Use the same pre-serve routine for both — disguise prevents the returner from reading early.','The kick generates more margin — use it when under pressure or on the second serve in big points.','The slice generates more horizontal movement — use it when you want to pull the returner wide.']::text[], ARRAY['Hitting a flat second serve instead of spin — results in double faults under pressure.','Always using the same type regardless of the call — not developing both spins.','Telegraphing the type through the toss — same toss for both is essential.']::text[], ARRAY['Player 2 calls the type they want — Player 1 must execute on command.','Serve out points: play full points with second serves only — kick or slice must be chosen before each.','Scoreboard: Player 1 loses a point for every double fault, Player 2 loses a point for misidentifying the spin.']::text[], ARRAY['serve','kick','slice','second serve','selection','advanced']::text[], 'json', '{"p1":{"x":200,"y":860},"p2":{"x":200,"y":60},"shots":[{"x1":200,"y1":850,"x2":240,"y2":385},{"x1":200,"y1":850,"x2":160,"y2":385}],"areas":[{"x":240,"y":385,"r":22},{"x":160,"y":385,"r":22}]}'::jsonb),
  ('SV-016', 'Serve Under Match Pressure: Tiebreak Simulation', 'Serve', 'Flat', 'serve', 'intermediate', 15, 2, 'pairs', 'Train the serve under the most pressure-intensive match condition — the tiebreak. The serve in a tiebreak is technically identical to any other serve, but most players tighten up, rush the motion, or completely change their approach under the stress of a close score. This drill replicates that pressure in practice so the serve becomes immune to tiebreak nerves.', 'Train the serve under the most pressure-intensive match condition — the tiebreak. The serve in a tiebreak is technically identical to any other serve, but most players tighten up, rush the motion, or completely change their approach under the stress of a close score. This drill replicates that pressure in practice so the serve becomes immune to tiebreak nerves.', 'Player 1 and Player 2 play a full tiebreak — 7 points, win by 2. Player 1 focuses specifically on serve quality: placement, first-serve percentage, and avoiding double faults. Player 2 returns aggressively and notes any changes in Player 1''s serve under pressure.', ARRAY['Play a full tiebreak from 0-0.','Player 1 tracks: first serve percentage, double faults, and placement accuracy.','Player 2 notes: does Player 1''s serve change as the score gets tight?','After the tiebreak, review: what changed? Did pace drop? Did placement become safer?','Play 3 tiebreaks per session. Use the data to identify serve tendencies under pressure.']::text[], ARRAY['Breathe before the ball toss — one slow exhale resets the nervous system.','Use your first serve in the tiebreak — don''t suddenly default to second-serve safety.','Slow your pre-serve routine down by one second — rushing is the first sign of nerves.','Stick to your planned placement — don''t suddenly serve to a new location under pressure.','The serve motion under pressure should feel identical to practice — if it feels different, something changed.']::text[], ARRAY['Suddenly serving safely and short — giving the opponent easy attack balls at critical moments.','Rushing the ball toss — creates all the downstream problems in the swing.','Changing planned serve location at the last second — indecision causes errors.']::text[], ARRAY['Start the tiebreak at 5-5 — maximum pressure from the first point.','Triple consequence: Player 1 serves a ''serve set'' — must win 5 consecutive serve games without double faults.','Partner tracking: Player 2 writes down every serve result — review after 3 tiebreaks.']::text[], ARRAY['serve','pressure','tiebreak','mental','intermediate','match-simulation']::text[], 'json', '{"p1":{"x":200,"y":860},"p2":{"x":200,"y":60},"shots":[{"x1":200,"y1":850,"x2":200,"y2":370},{"x1":200,"y1":850,"x2":315,"y2":390}],"areas":[{"x":200,"y":370,"r":22},{"x":315,"y":390,"r":22}]}'::jsonb),
  ('SV-017', 'Serve Rhythm: Consistent Pre-Serve Routine', 'Serve', 'Flat', 'serve', 'beginner', 10, 1, 'individual', 'Develop a consistent, repeatable pre-serve routine that anchors focus, controls breathing, and creates reliable muscle memory before every single serve. The pre-serve routine is one of the most undercoached aspects of the game — every professional player has one, and the consistency of that routine directly contributes to the consistency of the serve itself. This drill builds the habit from scratch.', 'Develop a consistent, repeatable pre-serve routine that anchors focus, controls breathing, and creates reliable muscle memory before every single serve. The pre-serve routine is one of the most undercoached aspects of the game — every professional player has one, and the consistency of that routine directly contributes to the consistency of the serve itself. This drill builds the habit from scratch.', 'Player 1 serves from both courts with an empty basket. No returner needed. The focus is entirely on what happens before the ball toss — the routine, the breath, the bounce, and the reset.', ARRAY['Player 1 establishes a pre-serve routine: bounce the ball 3 times, look at the target, exhale, toss.','Repeat this exact routine before every serve — no variations, no shortcuts.','Serve 20 balls maintaining the routine on every single one.','If Player 1 rushes or skips a step, they must stop and restart the routine from scratch.','After 20 serves, add a time pressure: Player 1 has exactly 25 seconds to complete the routine and serve.']::text[], ARRAY['The routine is not a delay — it is a reset. Use it as a tool, not a formality.','The exhale before the toss is the most important step — it releases shoulder tension.','Look at your target before the toss — your eyes set the aim before the motion starts.','Bounce the ball the same number of times every time — consistency in small things creates consistency in big things.','If you feel rushed, slow the routine down — never speed up the routine under pressure.']::text[], ARRAY['Skipping the routine when not under pressure — the routine only works if it is used every time.','Looking at the ground instead of the target before the toss.','Rushing through the routine — faster routine means more tension, not less.']::text[], ARRAY['Vary the bounce count — 2 bounces vs 5 bounces — find what feels best and stick with it.','Film the routine: check if it looks identical on every serve.','Partner times the routine: must be between 8-15 seconds from previous point ending to ball toss.']::text[], ARRAY['serve','routine','mental','beginner','consistency','solo']::text[], 'json', '{"p1":{"x":200,"y":860},"shots":[{"x1":200,"y1":850,"x2":200,"y2":390}],"areas":[{"x":200,"y":390,"r":35}]}'::jsonb),
  ('SV-018', 'Slice Serve Wide to Ad Court: Left-Hander''s Weapon', 'Serve', 'Slice', 'serve', 'advanced', 12, 2, 'pairs', 'Develop the wide slice serve from the ad court — a serve that curves sharply into the returner''s backhand corner. For right-handers, this serve is the equivalent of the wide deuce-court slice but on the opposite side. It is used to pull opponents off the court, create open-court opportunities on the ad side, and disrupt two-handed backhand returners who need room to swing. When hit correctly, it is extremely difficult to attack.', 'Develop the wide slice serve from the ad court — a serve that curves sharply into the returner''s backhand corner. For right-handers, this serve is the equivalent of the wide deuce-court slice but on the opposite side. It is used to pull opponents off the court, create open-court opportunities on the ad side, and disrupt two-handed backhand returners who need room to swing. When hit correctly, it is extremely difficult to attack.', 'Player 1 serves from the ad court baseline. Player 2 stands in the ad court return position. Player 1 targets the wide corner of the ad service box — as far toward the sideline as possible.', ARRAY['Player 1 serves wide slice serves from the ad court, targeting the far corner of the ad service box.','The serve must curve outward toward the sideline — pulling Player 2 wide.','Player 2 returns from the wide position — Player 1 notes how wide Player 2 had to move.','After the return, Player 1 attacks the open ad side with the plus-one shot.','Track: how many slices pull Player 2 at least 2 feet outside the sideline? Target: 6 of 10.']::text[], ARRAY['From the ad court, toss to the left for a wide slice — left of your normal toss position.','Contact the ball on the right side (3 o''clock) — same as the deuce court wide slice.','Follow through to the left — the cross-body motion drives the rightward curve from the ad side.','The serve curves away from a right-handed returner''s backhand — the discomfort is geometric.','After the serve, move right — the open court on the ad side is where the plus-one shot goes.']::text[], ARRAY['Toss too far right — cannot get across the ball from this position.','Serve going into the middle instead of wide — not enough cross-body brush.','Not following up the wide pull with a plus-one — wastes the opportunity.']::text[], ARRAY['Wide slice ad then drop shot: pull Player 2 wide then drop shot to the vacated ad side.','Mix ad wide and ad T: Player 2 must read which is coming.','Left-handed simulation: right-hander tries to replicate the left-hander''s wide slice trajectory — educational perspective.']::text[], ARRAY['serve','slice','wide','ad court','advanced','angle']::text[], 'json', '{"p1":{"x":160,"y":860},"p2":{"x":85,"y":60},"shots":[{"x1":160,"y1":850,"x2":80,"y2":388}],"areas":[{"x":80,"y":388,"r":20}],"cones":[{"x":80,"y":388}]}'::jsonb),
  ('SV-019', 'Serve First-Strike Tennis: Serve Plus Attack', 'Serve', 'Flat', 'serve', 'advanced', 15, 2, 'pairs', 'Develop first-strike tennis — the tactical approach of winning the point on the serve or the very next shot. First-strike tennis requires both a quality serve that limits the return and a pre-planned plus-one that attacks the expected return location. This drill trains the complete serve-plus-one package: placement, read, move, and execute — all as one fluid, pre-planned sequence.', 'Develop first-strike tennis — the tactical approach of winning the point on the serve or the very next shot. First-strike tennis requires both a quality serve that limits the return and a pre-planned plus-one that attacks the expected return location. This drill trains the complete serve-plus-one package: placement, read, move, and execute — all as one fluid, pre-planned sequence.', 'Before each point, Player 1 declares their planned pattern: for example, ''wide serve, plus-one forehand DTL''. Player 1 must execute exactly the declared pattern. Player 2 returns aggressively and plays out the point.', ARRAY['Player 1 declares the pattern before each point: serve target and plus-one target.','Player 1 must execute both shots exactly as declared — wrong shot counts as a tactical error.','Player 2 returns aggressively and plays out the point regardless.','After 5 points, swap the server.','Track: how many declared patterns were executed correctly? Target: 4 out of 5.']::text[], ARRAY['Plan the plus-one before the serve — not after seeing where the return goes.','Move to the plus-one position during the serve — your feet should be moving immediately.','Serve to create the expected return: wide serve creates CC return, T serve creates CC or DTL return.','The plus-one must be aggressive — a neutral plus-one defeats the purpose of first-strike tennis.','If the return doesn''t go where expected, adapt — but always have a default plan.']::text[], ARRAY['No pre-declaration — playing reactively instead of proactively.','Serve too weak — return is too aggressive to attack on the plus-one.','Plus-one not aggressive enough — giving the opponent a chance to reset.']::text[], ARRAY['Two-pattern alternation: Player 1 alternates between two declared patterns — keep Player 2 guessing.','First-strike points only: play a set where Player 1 must win within 3 shots or counts it as a loss.','Three-shot patterns: serve, plus-one, plus-two — declare all three before the point.']::text[], ARRAY['serve','first-strike','pattern','advanced','tactical','serve+1']::text[], 'json', '{"p1":{"x":280,"y":840},"p2":{"x":100,"y":60},"moves":[{"x1":240,"y1":855,"x2":280,"y2":840}],"shots":[{"x1":240,"y1":855,"x2":315,"y2":388},{"x1":100,"y1":70,"x2":245,"y2":800},{"x1":278,"y1":840,"x2":310,"y2":100}],"areas":[{"x":310,"y":100,"r":28}]}'::jsonb),
  ('SV-020', 'No-Double-Fault Challenge: 20 Serves In a Row', 'Serve', 'Kick', 'serve', 'intermediate', 10, 1, 'individual', 'Build complete double-fault immunity through a high-volume, zero-tolerance second serve consistency challenge. Double faults are the most damaging unforced error in tennis — they give the opponent a free point without touching the ball. This drill isolates second serve quality under a simple but powerful mental constraint: zero double faults allowed in 20 consecutive second serves.', 'Build complete double-fault immunity through a high-volume, zero-tolerance second serve consistency challenge. Double faults are the most damaging unforced error in tennis — they give the opponent a free point without touching the ball. This drill isolates second serve quality under a simple but powerful mental constraint: zero double faults allowed in 20 consecutive second serves.', 'Player 1 serves from alternating courts using second serve motion only — spin serve, no flat serves allowed. Any ball that misses the service box counts as a double fault. Any double fault resets the count to zero.', ARRAY['Player 1 serves from the deuce court with second-serve spin only.','Count consecutive makes — any miss resets the count to zero.','Alternate courts after every 5 serves: deuce, ad, deuce, ad.','Target: 20 consecutive second serves without a single double fault.','If 20 is reached, increase to 30. Record the personal best.']::text[], ARRAY['Commit fully to the spin — no flat second serves, no compromises.','A relaxed swing generates more spin than a tense one — breathe before each toss.','The double fault lives in hesitation — commit early and don''t second-guess mid-swing.','Aim for the middle third of the service box — not the corners on second serves.','Treat every serve identically — no special tension because the count is at 18.']::text[], ARRAY['Going for too much placement on second serves — reliability first, placement second.','Hesitating mid-swing — commits to neither spin nor direction, goes into the net.','Mental tightness as the count gets high — exactly the situation this drill trains for.']::text[], ARRAY['Timed version: how many second serves can land in 90 seconds?','Target: must land in the back half of the service box only — no shallow second serves.','Add a returner: play only second serve points — tests if consistency holds against real returns.']::text[], ARRAY['serve','second serve','consistency','kick','mental','intermediate']::text[], 'json', '{"p1":{"x":200,"y":860},"shots":[{"x1":200,"y1":850,"x2":240,"y2":385},{"x1":160,"y1":850,"x2":160,"y2":385}],"areas":[{"x":240,"y":385,"r":30},{"x":160,"y":385,"r":30}]}'::jsonb),
  ('SV-021', 'Serve Out Wide: Deuce Court Corner Precision', 'Serve', 'Flat', 'serve', 'intermediate', 10, 2, 'pairs', 'Develop precision targeting for the wide corner of the deuce service box — the most dangerous serve position from the deuce side. A flat or slice serve that clips the corner of the service box near the sideline forces the returner into an impossible position: they must move quickly to reach it, have almost no angle for their return, and their footing is compromised. Corner serves win free points at every level of the game.', 'Develop precision targeting for the wide corner of the deuce service box — the most dangerous serve position from the deuce side. A flat or slice serve that clips the corner of the service box near the sideline forces the returner into an impossible position: they must move quickly to reach it, have almost no angle for their return, and their footing is compromised. Corner serves win free points at every level of the game.', 'Place a cone in the corner of the deuce service box — 1 foot inside the sideline and 1 foot inside the service line. Player 1 serves from the deuce court baseline targeting the cone. Player 2 stands at the return position.', ARRAY['Player 1 serves from the deuce court, targeting the corner cone.','Score based on proximity: within 6 inches of the cone = 3 points, within 1 foot = 2 points, in the correct service box = 1 point.','Serve 15 balls per set. Target: 20+ points out of a possible 45.','Play 3 sets. Track improvement across sets.','After each set, Player 2 returns any serves that land — notes which are unreturnable.']::text[], ARRAY['The corner serve requires precise toss placement — toss slightly right for a slice corner, center for flat.','Aim for the sideline at net level — the geometry of the angle makes the ball land in the corner.','Don''t try to hit the cone directly — aim for the sideline, the angle takes the ball to the corner.','A slice corner serve curves away from the returner at the last moment — extremely difficult to reach.','Missing wide (outside the sideline) means you aimed correctly but need more topspin to bring it in.']::text[], ARRAY['Aiming at the cone directly instead of using the angle — sends the ball straight into the corner, not curving.','Missing the service box completely — toss position is too far right.','Going for the corner from a neutral serve position — need the right toss for each serve type.']::text[], ARRAY['Alternate corner and T: Player 2 must guess before each serve.','Corner serve percentage challenge: how high a percentage can Player 1 achieve across 30 serves?','Full point after corner: if the corner serve goes in, play the point — note how many win outright.']::text[], ARRAY['serve','flat','precision','deuce court','corner','intermediate']::text[], 'json', '{"p1":{"x":240,"y":860},"p2":{"x":290,"y":60},"shots":[{"x1":240,"y1":850,"x2":332,"y2":398}],"areas":[{"x":332,"y":398,"r":18}],"cones":[{"x":332,"y":398}]}'::jsonb),
  ('SV-022', 'Kick Serve Consistency from Ad Court: 15 in a Row', 'Serve', 'Kick', 'serve', 'intermediate', 12, 1, 'individual', 'Build reliable kick serve consistency from the ad court through a count-based challenge that escalates mental pressure as the consecutive number grows. The ad court kick serve is the standard second serve for most players — it must be completely reliable because a double fault from the ad court at deuce or ad-out is especially costly. This drill forces the quality needed to make the kick an asset rather than a liability.', 'Build reliable kick serve consistency from the ad court through a count-based challenge that escalates mental pressure as the consecutive number grows. The ad court kick serve is the standard second serve for most players — it must be completely reliable because a double fault from the ad court at deuce or ad-out is especially costly. This drill forces the quality needed to make the kick an asset rather than a liability.', 'Player 1 serves kick serves only from the ad court. Count consecutive makes. Any ball missing the service box resets the count to zero immediately. No returner needed — focus is purely on serve landing accuracy.', ARRAY['Player 1 serves kick serves from the ad court with consistent spin motion.','Count consecutive serves that land in the service box.','Any miss resets the count to zero — no exceptions.','Target: 15 consecutive kick serves without a miss.','Once 15 is achieved, move to the deuce court and repeat.']::text[], ARRAY['Toss consistently behind and slightly to the left — the foundation of every kick serve.','Commit fully to the 7-to-1 swing path on every ball — no flat-serve compromises.','Breathe between serves — the reset after a miss requires a mental and physical reset.','Spin is your safety net — the more topspin, the bigger the margin over the net.','Aim for the center of the service box — corners are for first serves, not second serves.']::text[], ARRAY['Going flat when the count is high and pressure builds — stick to the spin motion.','Rushing the toss — a hurried toss changes the contact point and kills the kick.','Giving up after resetting to zero — the mental recovery is part of the drill.']::text[], ARRAY['Target depth: kick serves must land past a cone placed halfway in the service box.','Both courts: 15 consecutive from ad, then immediately 15 from deuce — no break between.','Add location: odd-numbered serves to the wide corner, even-numbered to the center — placement plus consistency.']::text[], ARRAY['serve','kick','consistency','ad court','intermediate','second serve']::text[], 'json', '{"p1":{"x":160,"y":860},"shots":[{"x1":160,"y1":850,"x2":240,"y2":385},{"x1":160,"y1":850,"x2":200,"y2":400}],"areas":[{"x":240,"y":385,"r":25},{"x":165,"y":390,"r":25}]}'::jsonb),
  ('SV-023', 'Serve Return Analysis: Reading the Server', 'Serve', 'Flat', 'serve', 'advanced', 15, 2, 'pairs', 'Develop the ability to read and anticipate serve placement from early pre-serve cues — toss position, server''s stance, shoulder angle, and ball contact point. Reading the serve is one of the highest-value skills in tennis: a returner who can guess the correct serve location even 30% better than randomly dramatically improves their return quality. This drill trains both the server to conceal and the returner to read.', 'Develop the ability to read and anticipate serve placement from early pre-serve cues — toss position, server''s stance, shoulder angle, and ball contact point. Reading the serve is one of the highest-value skills in tennis: a returner who can guess the correct serve location even 30% better than randomly dramatically improves their return quality. This drill trains both the server to conceal and the returner to read.', 'Player 2 returns serves from Player 1. Player 2 must call the location before the ball lands — ''T'', ''wide'', or ''body''. Player 1 serves to varied locations attempting to disguise each one through identical pre-serve preparation.', ARRAY['Player 1 serves to any of the three zones without pre-declaring the location.','Player 2 must call the location — ''T'', ''wide'', or ''body'' — before the ball lands.','Track Player 2''s accuracy: correct calls out of total serves.','After 15 serves, Player 1 reveals which cues Player 2 was reading — toss, stance, or shoulder.','Switch roles. Repeat 3 rounds.']::text[], ARRAY['Returner: watch the toss first — it is the earliest, most reliable cue to serve location.','Returner: a toss further right (for right-hander) usually means wide from deuce court.','Server: keep the toss in the same position for all three serves — the hardest skill in serving.','Returner: watch the server''s shoulder at contact — where they face is often where the ball goes.','Server: use body rotation to disguise — turning the shoulder later hides the direction longer.']::text[], ARRAY['Returner guessing randomly instead of reading — not actually trying to read cues.','Server changing the toss for different serves — makes the serve too readable.','Returner reading the ball in flight instead of pre-contact cues — too late to adjust position.']::text[], ARRAY['Blindfold round: Player 1 covers their eyes during Player 2''s serve — pure toss-reading test.','Video analysis: film serves from the returner''s viewpoint — review which cues are visible.','Reading score: track Player 2''s accuracy over 10 sessions — improvement is measurable.']::text[], ARRAY['serve','return','reading','advanced','tactical','match-simulation']::text[], 'json', '{"p1":{"x":240,"y":860},"p2":{"x":170,"y":60},"shots":[{"x1":240,"y1":850,"x2":200,"y2":370},{"x1":240,"y1":850,"x2":318,"y2":390},{"x1":240,"y1":850,"x2":155,"y2":378}],"cones":[{"x":200,"y":370},{"x":318,"y":390},{"x":155,"y":378}]}'::jsonb),
  ('SV-024', 'Serve Then Baseline Rally: Full Point from the Start', 'Serve', 'Flat', 'serve', 'intermediate', 15, 2, 'pairs', 'Train the mental and physical transition from serving to rallying — a skill that many players practice separately but rarely combine. After serving, the server must transition immediately from the service motion into a ready position for a full baseline rally. Many players are mentally and physically caught out on the plus-one because their body is still in the serve motion. This drill creates a seamless serve-to-rally transition.', 'Train the mental and physical transition from serving to rallying — a skill that many players practice separately but rarely combine. After serving, the server must transition immediately from the service motion into a ready position for a full baseline rally. Many players are mentally and physically caught out on the plus-one because their body is still in the serve motion. This drill creates a seamless serve-to-rally transition.', 'Player 1 serves from both courts. Player 2 returns. Both players play out the full point from the serve — no fed balls, no second-chance practices. Every point starts with a real serve.', ARRAY['Player 1 serves from the deuce court — first serve, then second serve if needed.','Both players play the full point out — no replays.','Player 1 tracks: first serve percentage, rallying quality after the serve, and points won.','After 10 points from the deuce court, switch to the ad court for 10 more.','Track whether points won on first serve differ from points won on second serve.']::text[], ARRAY['Complete the serve motion fully before thinking about the rally — premature focus kills the serve.','After the serve, recover to center baseline for the plus-one — don''t stand near the service line.','Plan the plus-one before serving — know where you''re going to hit before the return arrives.','Watch the return from the moment it leaves Player 2''s racket — this is the key transition cue.','Stay physically loose after the serve — tension in the follow-through carries into the rally.']::text[], ARRAY['Not recovering to the baseline after the serve — gets caught at the service line for the rally.','Thinking about the rally during the serve — causes serving errors.','No pre-planned plus-one — reactive rally instead of proactive point construction.']::text[], ARRAY['Points only won on serve: Player 1 must win the point within 2 shots of the return or it counts as a loss.','Second serve only: forces use of spin serve then a real rally — harder transition.','Track 30 points: compare first serve win percentage vs second serve win percentage.']::text[], ARRAY['serve','rally','transition','match-simulation','intermediate','full point']::text[], 'json', '{"p1":{"x":200,"y":840},"p2":{"x":200,"y":60},"moves":[{"x1":240,"y1":855,"x2":200,"y2":840}],"shots":[{"x1":240,"y1":855,"x2":200,"y2":370},{"x1":200,"y1":70,"x2":280,"y2":810},{"x1":200,"y1":840,"x2":100,"y2":100}],"areas":[{"x":100,"y":100,"r":30}]}'::jsonb),
  ('SV-025', 'Serve Into the Wind: Adapting Toss Under Conditions', 'Serve', 'Flat', 'serve', 'intermediate', 10, 1, 'individual', 'Train the ability to adapt the serve under difficult outdoor conditions — specifically wind. Wind is the most unpredictable external factor in tennis, and the serve is the most affected shot because the toss is exposed for 1-2 seconds in open air before contact. This drill builds the habit of reading wind conditions, adjusting the toss placement, and choosing the right serve type for the conditions.', 'Train the ability to adapt the serve under difficult outdoor conditions — specifically wind. Wind is the most unpredictable external factor in tennis, and the serve is the most affected shot because the toss is exposed for 1-2 seconds in open air before contact. This drill builds the habit of reading wind conditions, adjusting the toss placement, and choosing the right serve type for the conditions.', 'This drill is designed for outdoor courts on a windy day. Player 1 serves into and with the wind from both courts. The drill teaches adaptation, not perfection — consistency under adverse conditions.', ARRAY['Serve 10 balls into the wind — notice how it affects the toss and serve direction.','Adapt the toss: lower the toss into a headwind, keep it more controlled in a crosswind.','Serve 10 balls with the wind — notice that a flat serve may go long.','With the wind, add more topspin or aim deeper in the service box.','Track: first serve percentage into the wind vs with the wind.']::text[], ARRAY['Into the wind: lower the toss by 6-12 inches — less time in the air means less drift.','Into the wind: add more topspin — the headwind adds bounce height and keeps the serve in.','With the wind: aim slightly shorter in the service box — the wind will carry the ball longer.','Crosswind: adjust toss toward the wind so it drifts back to the ideal contact zone.','Never fight the wind — adapt to it. Trying to serve through conditions always causes more errors.']::text[], ARRAY['Keeping the same toss in windy conditions — the toss drifts and contact is wrong.','Getting frustrated instead of adapting — wind is equal for both players, use it strategically.','Not using more spin with the wind — flat serves go long when serving downwind.']::text[], ARRAY['Serve chart: track which serve types work best in each wind direction — build a personal wind reference.','Into-wind vs downwind serve percentage: compare first-serve in-percentage in both directions.','Use the wind as a weapon: kick serve into crosswind — the kick and wind combine for extreme curve.']::text[], ARRAY['serve','conditions','wind','adaptation','intermediate','outdoor']::text[], 'json', '{"p1":{"x":200,"y":860},"shots":[{"x1":200,"y1":850,"x2":200,"y2":380},{"x1":160,"y1":850,"x2":220,"y2":388}],"areas":[{"x":200,"y":380,"r":35},{"x":220,"y":388,"r":35}]}'::jsonb),
  ('SV-026', 'Deuce Court Serve Variety: Four Patterns in One Session', 'Serve', 'Flat', 'serve', 'intermediate', 15, 2, 'pairs', 'Develop four distinct serving patterns from the deuce court and train the ability to execute each one cleanly within the same practice session. Serving variety is what keeps returners guessing — a server who uses only one or two patterns becomes predictable and readable. This drill builds the habit of rotating between all four deuce court patterns: T flat, wide slice, body flat, and T kick.', 'Develop four distinct serving patterns from the deuce court and train the ability to execute each one cleanly within the same practice session. Serving variety is what keeps returners guessing — a server who uses only one or two patterns becomes predictable and readable. This drill builds the habit of rotating between all four deuce court patterns: T flat, wide slice, body flat, and T kick.', 'Player 1 serves from the deuce court. Player 2 returns. Player 1 cycles through all four patterns in rotation — T flat, wide slice, body flat, T kick — without pre-declaring which is coming.', ARRAY['Player 1 serves in a rotating pattern: T flat, wide slice, body flat, T kick — repeating the cycle.','Player 2 returns and calls the pattern after each serve: ''T flat'', ''wide slice'', etc.','If Player 2 identifies the pattern correctly, it reveals Player 1 is telegraphing — adjust.','After 20 serves (5 of each), play out full points in random order.','Track: first serve percentage for each pattern and which patterns Player 2 reads most often.']::text[], ARRAY['Each pattern requires a slightly different toss — practice the toss for each separately.','The body serve toss is the most similar to the T serve — use this similarity to disguise.','The kick toss goes furthest back — this is the hardest toss to hide.','Rotate patterns every point in a match — never serve to the same zone twice in a row.','If Player 2 reads 3 of 4 patterns, you are telegraphing — the toss is almost always the tell.']::text[], ARRAY['Only serving comfortably with 2 patterns — the other 2 become obvious when used.','Rotating predictably (always T, wide, body, kick in that order) — Player 2 anticipates the sequence.','Different pre-serve bouncing routine for different serves — an early giveaway.']::text[], ARRAY['Player 2 tries to guess each pattern before the serve lands — tracks reading accuracy.','Best pattern game: which pattern wins the most points in 20 serves? Track results.','Second serve variety: add kick and slice to the rotation — 6-pattern serve vocabulary.']::text[], ARRAY['serve','variety','deuce court','patterns','intermediate','tactical']::text[], 'json', '{"p1":{"x":240,"y":860},"p2":{"x":160,"y":60},"shots":[{"x1":240,"y1":850,"x2":200,"y2":370},{"x1":240,"y1":850,"x2":318,"y2":390},{"x1":240,"y1":850,"x2":148,"y2":378},{"x1":240,"y1":850,"x2":202,"y2":375}],"cones":[{"x":200,"y":370},{"x":318,"y":390},{"x":148,"y":378}]}'::jsonb),
  ('SV-027', 'Slice Serve Plus Net Rush: Slice and Charge', 'Serve', 'Slice', 'serve', 'advanced', 12, 2, 'pairs', 'Develop the slice serve and charge pattern — using a wide slice serve to pull the opponent off the court, then rushing the net behind it. The slice serve is ideal for this pattern because the wide angle it creates gives the server a direct path to the net while the returner is off-balance. This is a classic grass-court and fast-court tactic that creates immediate pressure and forces a difficult low pass.', 'Develop the slice serve and charge pattern — using a wide slice serve to pull the opponent off the court, then rushing the net behind it. The slice serve is ideal for this pattern because the wide angle it creates gives the server a direct path to the net while the returner is off-balance. This is a classic grass-court and fast-court tactic that creates immediate pressure and forces a difficult low pass.', 'Player 1 serves a wide slice from the deuce court, then immediately rushes the net. Player 2 returns from a wide position and attempts a passing shot. Player 1 must split step and volley.', ARRAY['Player 1 serves a wide slice from the deuce court.','Immediately after the serve, Player 1 sprints toward the net.','Player 2 returns from an off-balance wide position — the return will likely be weak or floating.','Player 1 split steps as Player 2 contacts the return and volleys the finish.','Play out each point. Repeat 15 times. Track: how many net rushes after slice serve result in a won point?']::text[], ARRAY['The wider the slice serve, the weaker the return — a great wide slice makes the net rush easy.','Start moving toward the net the instant the serve leaves the racket.','Sprint on a diagonal toward the net — not straight ahead, aim toward the expected return landing zone.','Split step right as Player 2''s racket contacts the ball — before the ball is in the air.','From the wide volley position, aim cross-court into the open court — not down the line.']::text[], ARRAY['Not sprinting hard enough after the serve — arrives at the net too late for the volley.','Wide slice not wide enough — weak pull means Player 2 returns comfortably.','No split step — cannot change direction without the split, volley is always late.']::text[], ARRAY['Slice and charge from ad court — different angle, same pattern.','Kick serve and charge: kick to backhand then rush net — forces a high defensive return.','Double rush: serve and charge on both first and second serve — maximum aggression.']::text[], ARRAY['serve','slice','net rush','advanced','volley','deuce court']::text[], 'json', '{"p1":{"x":310,"y":560},"p2":{"x":340,"y":60},"moves":[{"x1":240,"y1":855,"x2":310,"y2":560}],"shots":[{"x1":240,"y1":855,"x2":325,"y2":388},{"x1":340,"y1":70,"x2":275,"y2":620},{"x1":305,"y1":555,"x2":100,"y2":120}],"areas":[{"x":100,"y":120,"r":25}]}'::jsonb),
  ('SV-028', 'Serve Return Practice: Block and Drive', 'Serve', 'Flat', 'serve', 'intermediate', 12, 2, 'pairs', 'Train two distinct return techniques — the block return (compact, absorbing pace) and the drive return (full swing, adding pace) — and develop the judgment to know when to use each. The block return is used on fast, wide serves when there is no time for a full swing. The drive return is used on slower, more central serves when there is room to step in and attack. Most players use one exclusively — this drill builds both.', 'Train two distinct return techniques — the block return (compact, absorbing pace) and the drive return (full swing, adding pace) — and develop the judgment to know when to use each. The block return is used on fast, wide serves when there is no time for a full swing. The drive return is used on slower, more central serves when there is room to step in and attack. Most players use one exclusively — this drill builds both.', 'Player 1 serves alternating fast and medium-pace serves to Player 2. Player 2 must identify which type is coming and use the correct return technique — block for fast serves, drive for slower ones.', ARRAY['Player 1 alternates: one fast serve (Player 2 should block), then one medium serve (Player 2 should drive).','Player 2 calls ''block'' or ''drive'' before each return — commits to the technique.','After 10 alternating serves, Player 1 mixes randomly — Player 2 must read and react.','Track: how often does Player 2 choose the correct technique? Target: 8 of 10.','Play 4 rounds of 10 serves each.']::text[], ARRAY['Block return: racket up and firm before the ball arrives, short compact swing, redirect the pace.','Drive return: step in, take a full backswing, drive through the ball adding your own pace.','Key decision cue: how much time do you have? Fast serve = block. Time to set up = drive.','On the block return, the firm wrist is everything — a loose wrist kills direction control.','On the drive return, step forward into the ball — momentum drives the return deep.']::text[], ARRAY['Trying to drive a fast serve — results in a mis-hit or late contact.','Blocking a slow serve — wastes a free attack opportunity.','No decision before the serve — reacting instead of reading.']::text[], ARRAY['Block to specific target: block returns must go cross-court only.','Drive return aggression: drive return must be a winner or force an error within 2 shots.','Three-technique version: add a slice chipped return as a third option for wide serves.']::text[], ARRAY['serve','return','block','drive','technique','intermediate']::text[], 'json', '{"p1":{"x":240,"y":860},"p2":{"x":160,"y":60},"shots":[{"x1":240,"y1":850,"x2":310,"y2":390},{"x1":240,"y1":850,"x2":200,"y2":375},{"x1":310,"y1":390,"x2":240,"y2":820},{"x1":200,"y1":375,"x2":100,"y2":800}],"areas":[{"x":240,"y":820,"r":25},{"x":100,"y":800,"r":25}]}'::jsonb),
  ('SV-029', 'Serve Percentage Tracking: First and Second', 'Serve', 'Flat', 'serve', 'beginner', 15, 2, 'pairs', 'Measure and improve serve percentages through systematic tracking — the most data-driven serve drill available. Most players have no idea what their actual first and second serve percentages are, which makes it impossible to improve them deliberately. This drill creates immediate awareness through real-time tracking and identifies exactly where the serve breaks down: toss, swing, or placement.', 'Measure and improve serve percentages through systematic tracking — the most data-driven serve drill available. Most players have no idea what their actual first and second serve percentages are, which makes it impossible to improve them deliberately. This drill creates immediate awareness through real-time tracking and identifies exactly where the serve breaks down: toss, swing, or placement.', 'Player 1 serves a full set of serves (30 first serves and 30 second serves). Player 2 tracks every serve: in or out, fault type (long, wide, net), and approximate landing location.', ARRAY['Player 1 serves 30 first serves from alternating deuce and ad courts.','Player 2 records: in or out, and if out — long, wide, or net.','Calculate first serve percentage after 30 serves.','Player 1 serves 30 second serves — same tracking.','After the session, review the data: what is the most common fault type? Where does the ball land when it goes in?']::text[], ARRAY['Long faults on flat serves: too much pace, not enough topspin to bring it down.','Wide faults: toss position too far to the side, or swing angle off.','Net faults: contact point too low, or not enough leg drive.','Use the data, not feelings — players almost always think their percentage is higher than it actually is.','Target first serve: 60%+ in. Target second serve: 90%+ in.']::text[], ARRAY['Not tracking honestly — every fault must be recorded, not just remembered selectively.','Serving differently because of tracking — must serve naturally for the data to be useful.','Ignoring the fault type data — knowing where it goes wrong is more valuable than just knowing the percentage.']::text[], ARRAY['Track placements: where in the service box does each serve land? Map patterns.','Weekly tracking: repeat this drill weekly for one month — measure the improvement.','Match day tracking: use a simple tally during a real match — compare practice vs match percentages.']::text[], ARRAY['serve','tracking','percentage','beginner','data','both courts']::text[], 'json', '{"p1":{"x":200,"y":860},"p2":{"x":200,"y":60},"shots":[{"x1":240,"y1":855,"x2":200,"y2":370},{"x1":160,"y1":855,"x2":160,"y2":390}],"cones":[{"x":200,"y":370},{"x":310,"y":390},{"x":148,"y":378},{"x":160,"y":390}]}'::jsonb),
  ('SV-030', 'Kick Serve: Toss Position Isolation', 'Serve', 'Kick', 'serve', 'intermediate', 10, 1, 'individual', 'Isolate and train the ball toss specifically for the kick serve — the most different and most misunderstood toss in all of serving. The kick serve toss goes behind the head and slightly to the left (for right-handers), completely opposite from the flat or slice serve toss. Getting this toss position consistently correct is the single most important step in developing a reliable kick serve — without the right toss, no kick is possible.', 'Isolate and train the ball toss specifically for the kick serve — the most different and most misunderstood toss in all of serving. The kick serve toss goes behind the head and slightly to the left (for right-handers), completely opposite from the flat or slice serve toss. Getting this toss position consistently correct is the single most important step in developing a reliable kick serve — without the right toss, no kick is possible.', 'Player 1 stands at the baseline with balls only — no racket for Phase 1. Player 1 practices tossing the ball to the kick serve position and letting it land, marking where it falls. A cone marks the ideal landing spot.', ARRAY['Phase 1: Player 1 tosses to kick serve position without a racket — ball should land behind the left foot.','Toss 15 balls to the kick position. Mark where they land. Target: within 6 inches of the cone.','Phase 2: add the swing — toss and serve, using only kick serve motion.','Track: how many kick serves land in the service box vs how many flat serves would normally land in.','Notice the feel difference between the kick toss and the flat serve toss.']::text[], ARRAY['Kick toss goes behind your head and to the left — directly above or slightly left of the left foot.','Flat serve toss goes in front and to the right — the two tosses are in completely different positions.','If the kick toss lands in front of you, it is a flat serve toss — it must land behind.','Keep the tossing arm straight all the way up — bending creates inconsistency.','Practice the toss 50 times without hitting — perfect toss position before adding the swing.']::text[], ARRAY['Kick toss landing too far in front — makes it physically impossible to generate kick spin.','Tossing too far to the right — removes the ability to swing 7 to 1 across the ball.','Inconsistent toss height — too high or too low changes the swing timing completely.']::text[], ARRAY['Side-by-side toss comparison: alternate flat toss and kick toss — feel the difference clearly.','Film the toss: use slow motion video to verify the toss lands behind the left foot.','Partner hold: Player 2 holds a racket at the ideal kick toss position — Player 1 tosses to touch it.']::text[], ARRAY['serve','kick','toss','technique','intermediate','solo']::text[], 'json', '{"p1":{"x":200,"y":860},"shots":[{"x1":200,"y1":850,"x2":200,"y2":388}],"areas":[{"x":200,"y":388,"r":30}],"cones":[{"x":185,"y":830}]}'::jsonb)
